  Ciphertext e3 = t + t - one;
  Ciphertext t4 = square(t);
  t4 = t4 + t4 - one;
  Ciphertext e5 = t4 + t4 - e3;
  Ciphertext q = t4 * c7;
  Ciphertext w = q + q + c3;
  Ciphertext r = e5 * c5;
  r = r - c7;
  r = r + c1;
  Ciphertext s = e3 * w + r;
  Ciphertext result = z * s + c0;
  result.set_output("y");
